ed_element": "AI generated hand with 6 fingers holding water bottle", "client_feedback": "Obvious AI distortion in hands, embarrassing to post.", "corrective_rule": "Vision QA must flag any hand/finger deformities or blurred text before client preview."}], "aliases": ["apex", "apex athletics"], "slack_channel_ids": [], "limits": {"max_images_per_day": 40}, "default_audience": "Athletes, fitness professionals and high performers aged 22-45", "requires_product_photos": false}, "maria_b_study": {"client_id": "maria_b_study", "company_name": "Maria.B. (study example)", "public_facts": {"founder": "Maria Butt", "founded": "1999, Lahore, Pakistan", "stores": "38 locations as of 2025", "product_lines": ["Lawn", "Linen", "Sateen", "Silk", "Eid Lawn", "Evening Wear", "Couture", "Bridals", "Mbroidered", "MPrints", "MBasics", "Casuals", "Mkids", "Jewellery", "Perfumes"], "known_for": "Embroidered and embellished collections for everyday, festive and bridal wear", "source": "https://en.wikipedia.org/wiki/Maria_B"}, "brand_guidelines": {"mission": "ASSUMED: Make Pakistani women feel luxurious and confident, from everyday lawn to bridal couture", "tone_of_voice": ["Elegant", "Confident", "Warm", "Celebratory", "Premium but not distant"], "color_palette": {"primary_hex": "#111111", "secondary_hex": "#B08D57", "accent_hex": "#7A1F3D", "background_hex": "#FAF7F2"}, "typography_rules": {"headline_font": "ASSUMED: high-contrast serif or refined sans, Latin script only (AI image models spell Urdu script badly)", "casing": "Title Case or lowercase for elegance, never shouting ALL CAPS", "max_text_characters": 20}, "banned_elements": ["No discount badges, red or yellow sale stickers, or clipart", "No AI-generated garments (customers expect the exact real product). Use real product photos, AI only for layout, background and copy", "No distorted hands, faces, or embroidery that looks melted", "No competitor brand names or lookalike logos", "No unverified claims such as 'best in Pakistan'"]}, "collection_context": {"ASSUMED_audience": "Women 20-45 in Pakistan and the diaspora (UK, US, UAE) shopping for lawn, festive, wedding and bridal", "ASSUMED_seasons": ["Summer lawn", "Eid festive", "Winter linen and velvet", "Wedding season", "Bridal couture"], "ASSUMED_social": {"instagram": "4:5 (1080x1350) for product and lookbook, 9:16 for Reels covers", "caption_structure": "1. Short elegant hook\n2. 1-2 lines about fabric or embroidery\n3. Clear CTA (shop now, visit store)\n4. 6-8 hashtags"}}, "approved_past_work": [], "rejection_history": [], "_note": "STUDY DRAFT: public_facts come from Wikipedia. Colors, tone and banned elements are ASSUMED, not Maria B's official guidelines. approved_past_work and rejection_history are empty on purpose: fill them from the real client.", "aliases": ["maria b", "maria.b", "mariab"], "slack_channel_ids": [], "limits": {"max_images_per_day": 40}, "default_audience": "Women 20-45 in Pakistan and the diaspora shopping for lawn, festive, wedding and bridal wear", "requires_product_photos": true}};
const OPTIONS = {"platforms": [{"id": "ig_feed_4x5", "label": "Instagram Feed 4:5 (1080x1350)", "ratio": "4:5 portrait (1080x1350)", "aspect": "ASPECT_4_5"}, {"id": "square_1x1", "label": "Square 1:1 (Instagram, Facebook)", "ratio": "1:1 square (1080x1080)", "aspect": "ASPECT_1_1"}, {"id": "story_9x16", "label": "Story or Reel cover 9:16", "ratio": "9:16 vertical (1080x1920)", "aspect": "ASPECT_9_16"}, {"id": "landscape_16x9", "label": "Landscape 16:9 (Facebook, LinkedIn, X)", "ratio": "16:9 landscape", "aspect": "ASPECT_16_9"}], "objectives": [{"id": "brand_awareness", "label": "Brand awareness"}, {"id": "product_launch", "label": "Product or collection launch"}, {"id": "sale_promo", "label": "Sale or offer"}, {"id": "festival_event", "label": "Festival or event (Eid, wedding season)"}, {"id": "engagement", "label": "Engagement and community"}], "assets": [{"id": "will_attach", "label": "I will attach real product photos"}, {"id": "none", "label": "No photos, an AI-made image is fine"}]};

const e = $input.first().json.body.event;
const sd = $getWorkflowStaticData('global');
sd.jobs = sd.jobs || {};
sd.learned = sd.learned || {};
sd.usage = sd.usage || {};

const now = Date.now();
for (const [k, j] of Object.entries(sd.jobs)) {
  if (now - j.created > 14 * 86400 * 1000) delete sd.jobs[k];
}

let text = (e.text || '').replace(/<@[A-Z0-9]+>/g, '').trim();
let clientId = null;
const tag = text.match(/client:\s*([a-z0-9_-]+)/i);
if (tag) {
  clientId = tag[1].toLowerCase();
  text = text.replace(tag[0], '').trim();
}
const skipIntake = /--quick\b/i.test(text);
text = text.replace(/--quick\b/gi, '').trim();

const ids = Object.keys(BRAINS);
if (!clientId || !BRAINS[clientId]) {
  const lower = text.toLowerCase();
  clientId =
    ids.find((id) => (BRAINS[id].slack_channel_ids || []).includes(e.channel)) ||
    ids.find((id) => (BRAINS[id].aliases || []).some((a) => lower.includes(a.toLowerCase()))) ||
    ($env.DEFAULT_CLIENT_ID && BRAINS[$env.DEFAULT_CLIENT_ID] ? $env.DEFAULT_CLIENT_ID : ids[0]);
}
const brain = BRAINS[clientId];
const guide = brain.brand_guidelines || {};
const learned = sd.learned[clientId] || [];

const day = new Date().toISOString().slice(0, 10);
const limit = (brain.limits && brain.limits.max_images_per_day) || Number($env.DAILY_IMAGE_LIMIT) || 40;
const used = (sd.usage[clientId] && sd.usage[clientId][day]) || 0;
const withinLimit = used + 1 <= limit;

const banned = guide.banned_elements || [];
const rejections = []
  .concat((brain.rejection_history || []).map((r) => `${r.rejected_element} -> rule: ${r.corrective_rule}`))
  .concat(learned.map((r) => `${r.client_feedback} -> rule: ${r.corrective_rule}`));
const golden = (brain.approved_past_work || []).map(
  (a) => `${a.campaign_name}: ${a.visual_style_description} | headline "${a.headline}"`
);
const maxChars = (guide.typography_rules && guide.typography_rules.max_text_characters) || 25;

const brainPrompt = `You are the Executive Creative Director of an elite agency working for the client "${brain.company_name}".

CLIENT BRAIN
Brand guidelines (JSON): ${JSON.stringify(guide)}
Context (JSON): ${JSON.stringify(brain.collection_context || brain.public_facts || {})}
Past approved work to emulate: ${golden.length ? golden.join(' | ') : 'none yet'}
Mistakes to NEVER repeat: ${rejections.length ? rejections.join(' | ') : 'none yet'}
Headlines printed on images: maximum ${maxChars} characters, Latin script. Never use banned elements.`;

const intakeSystem = `You extract a social media design brief from a client's Slack message.
Only use what the message clearly states. Never guess. Use null for anything not stated.
Return ONLY JSON: {"platform": <id or null>, "objective": <id or null>, "product_focus": <string or null>, "audience": <string or null>, "visual_style": <string or null>, "assets": <id or null>}
platform ids: ${OPTIONS.platforms.map((p) => `${p.id} (${p.label})`).join('; ')}
objective ids: ${OPTIONS.objectives.map((o) => `${o.id} (${o.label})`).join('; ')}
assets ids: will_attach (the message says real photos are attached or provided), none (the message says there are no photos)
product_focus: the specific product, collection or offer. audience: who it is for. visual_style: the look or mood asked for.`;

let jobId = null;
if (withinLimit) {
  jobId = 'job_' + now.toString(36) + Math.random().toString(36).slice(2, 6);
  sd.jobs[jobId] = {
    client_id: clientId,
    channel: e.channel,
    thread_ts: e.thread_ts || e.ts,
    request: text,
    status: 'intake',
    created: now,
    revision: 0,
    limit,
    qa_rules: banned.join('; '),
    qa_warnings: 0,
    brain_prompt: brainPrompt,
    requires_photos: !!brain.requires_product_photos,
    default_audience: brain.default_audience || '',
    brand_name: brain.company_name,
  };
}

return [{
  json: {
    job_id: jobId,
    client_id: clientId,
    brand_name: brain.company_name,
    channel: e.channel,
    thread_ts: e.thread_ts || e.ts,
    within_limit: withinLimit,
    limit,
    used,
    skip_intake: skipIntake,
    has_files: Array.isArray(e.files) && e.files.length > 0,
    intake_system_prompt: intakeSystem,
    intake_user_prompt: text || 'No details given.',
  },
}];

// Tells the team the daily image limit was reached.
const c = $input.first().json;
return [{
  json: {
    slack_url: 'https://slack.com/api/chat.postMessage',
    slack_payload: {
      channel: c.channel,
      thread_ts: c.thread_ts,
      text: `:no_entry: Daily image limit reached for ${c.brand_name} (${c.used} of ${c.limit} images used today). Try again tomorrow or raise "limits.max_images_per_day" in the client brain.`,
    },
  },
}];

// Validates the extracted brief in code (does not trust the model) and decides:
// complete -> go straight to planning, or incomplete -> ask the client.
const OPTIONS = {"platforms": [{"id": "ig_feed_4x5", "label": "Instagram Feed 4:5 (1080x1350)", "ratio": "4:5 portrait (1080x1350)", "aspect": "ASPECT_4_5"}, {"id": "square_1x1", "label": "Square 1:1 (Instagram, Facebook)", "ratio": "1:1 square (1080x1080)", "aspect": "ASPECT_1_1"}, {"id": "story_9x16", "label": "Story or Reel cover 9:16", "ratio": "9:16 vertical (1080x1920)", "aspect": "ASPECT_9_16"}, {"id": "landscape_16x9", "label": "Landscape 16:9 (Facebook, LinkedIn, X)", "ratio": "16:9 landscape", "aspect": "ASPECT_16_9"}], "objectives": [{"id": "brand_awareness", "label": "Brand awareness"}, {"id": "product_launch", "label": "Product or collection launch"}, {"id": "sale_promo", "label": "Sale or offer"}, {"id": "festival_event", "label": "Festival or event (Eid, wedding season)"}, {"id": "engagement", "label": "Engagement and community"}], "assets": [{"id": "will_attach", "label": "I will attach real product photos"}, {"id": "none", "label": "No photos, an AI-made image is fine"}]};
const ctx = $('Load Brain & Build Prompt').last().json;
const sd = $getWorkflowStaticData('global');
const job = sd.jobs && sd.jobs[ctx.job_id];
if (!job) throw new Error('Job not found: ' + ctx.job_id);

let x = {};
try {
  x = JSON.parse($input.first().json.choices[0].message.content);
} catch (err) {
  x = {};
}
const pick = (list, v) => (list.some((o) => o.id === v) ? v : null);
const clean = (s) =>
  typeof s === 'string' && s.trim() && !/^(null|none|n\/a|unknown|not stated)$/i.test(s.trim()) ? s.trim().slice(0, 300) : null;

const brief = {
  platform: pick(OPTIONS.platforms, x.platform),
  objective: pick(OPTIONS.objectives, x.objective),
  product_focus: clean(x.product_focus),
  audience: clean(x.audience),
  visual_style: clean(x.visual_style),
  assets: pick(OPTIONS.assets, x.assets),
};
if (ctx.has_files) brief.assets = 'will_attach';

if (ctx.skip_intake) {
  brief.platform = brief.platform || 'ig_feed_4x5';
  brief.objective = brief.objective || 'brand_awareness';
  brief.product_focus = brief.product_focus || job.request || 'the brand';
  brief.assets = brief.assets || 'none';
}

const missing = [];
if (!brief.platform) missing.push('platform');
if (!brief.objective) missing.push('objective');
if (!brief.product_focus) missing.push('product_focus');
if (job.requires_photos && !brief.assets) missing.push('assets');

if (missing.length === 0) {
  job.brief = brief;
  job.status = 'planning';
  return [{ json: { complete: true, job_id: ctx.job_id } }];
}

job.brief_draft = brief;
job.status = 'awaiting_intake';
return [{
  json: { complete: false, job_id: ctx.job_id, channel: job.channel, thread_ts: job.thread_ts, brief, missing },
}];

// Posts the "I need a few details" message: what was understood, what is missing, and a button to open the form.
const OPTIONS = {"platforms": [{"id": "ig_feed_4x5", "label": "Instagram Feed 4:5 (1080x1350)", "ratio": "4:5 portrait (1080x1350)", "aspect": "ASPECT_4_5"}, {"id": "square_1x1", "label": "Square 1:1 (Instagram, Facebook)", "ratio": "1:1 square (1080x1080)", "aspect": "ASPECT_1_1"}, {"id": "story_9x16", "label": "Story or Reel cover 9:16", "ratio": "9:16 vertical (1080x1920)", "aspect": "ASPECT_9_16"}, {"id": "landscape_16x9", "label": "Landscape 16:9 (Facebook, LinkedIn, X)", "ratio": "16:9 landscape", "aspect": "ASPECT_16_9"}], "objectives": [{"id": "brand_awareness", "label": "Brand awareness"}, {"id": "product_launch", "label": "Product or collection launch"}, {"id": "sale_promo", "label": "Sale or offer"}, {"id": "festival_event", "label": "Festival or event (Eid, wedding season)"}, {"id": "engagement", "label": "Engagement and community"}], "assets": [{"id": "will_attach", "label": "I will attach real product photos"}, {"id": "none", "label": "No photos, an AI-made image is fine"}]};
const i = $input.first().json;
const b = i.brief;
const label = (list, id) => (list.find((o) => o.id === id) || {}).label;

const rows = [
  ['Where will it be posted (size)', label(OPTIONS.platforms, b.platform)],
  ['Goal of the campaign', label(OPTIONS.objectives, b.objective)],
  ['Product or collection', b.product_focus],
  ['Target audience', b.audience],
  ['Look and mood', b.visual_style],
  ['Real product photos', label(OPTIONS.assets, b.assets)],
];
const lines = rows.map(([name, value]) => (value ? `:white_check_mark: *${name}:* ${value}` : `:grey_question: *${name}:* not stated`));

return [{
  json: {
    slack_url: 'https://slack.com/api/chat.postMessage',
    slack_payload: {
      channel: i.channel,
      thread_ts: i.thread_ts,
      text: 'I need a few details before I design. Please answer the quick questions.',
      blocks: [
        {
          type: 'section',
          text: {
            type: 'mrkdwn',
            text: '*Before I design, I need a few details.* Answering them now means the first draft has the right size, goal and style, so you do not need to ask for changes later.',
