    qa_rules: job.qa_rules,
    qa_min_score: 80,
    card_channel: job.card_channel,
    card_ts: job.card_ts,
    approved_by: r.user_id,
  },
}));

// Discard button: marks the job discarded and replaces the card so the buttons disappear.
const r = $input.first().json;
const sd = $getWorkflowStaticData('global');
const job = sd.jobs && sd.jobs[r.job_id];
if (job) job.status = 'discarded';
return [{
  json: {
    slack_url: 'https://slack.com/api/chat.update',
    slack_payload: {
      channel: r.channel,
      ts: r.message_ts,
      text: 'Draft discarded',
      blocks: [{
        type: 'section',
        text: { type: 'mrkdwn', text: `:x: Draft discarded by <@${r.user_id}>. No more images will be generated for this job.` },
      }],
    },
  },
}];

// Request Changes button: opens a Slack modal asking what should change.
const r = $input.first().json;
const sd = $getWorkflowStaticData('global');
const job = sd.jobs && sd.jobs[r.job_id];
const title = { type: 'plain_text', text: 'Request changes' };

let view;
if (!job || job.status !== 'awaiting_review') {
  view = {
    type: 'modal',
    title,
    close: { type: 'plain_text', text: 'Close' },
    blocks: [{ type: 'section', text: { type: 'mrkdwn', text: 'This draft is no longer waiting for review.' } }],
  };
} else {
  job.card_channel = r.channel;
  job.card_ts = r.message_ts;
  view = {
    type: 'modal',
    callback_id: 'edit_modal',
    private_metadata: r.job_id,
    title,
    submit: { type: 'plain_text', text: 'Regenerate' },
    close: { type: 'plain_text', text: 'Cancel' },
    blocks: [{
      type: 'input',
      block_id: 'notes_block',
      label: { type: 'plain_text', text: 'What should change?' },
      element: {
        type: 'plain_text_input',
        action_id: 'notes_input',
        multiline: true,
        placeholder: { type: 'plain_text', text: 'e.g. softer lighting, show more embroidery detail, move the text higher' },
      },
    }],
  };
}

return [{
  json: {
    slack_url: 'https://slack.com/api/views.open',
    slack_payload: { trigger_id: r.trigger_id, view },
  },
}];

// Modal submit: saves the feedback as a learned rule for this client and queues a revised Post 1.
const r = $input.first().json;
const sd = $getWorkflowStaticData('global');
const job = sd.jobs && sd.jobs[r.job_id];

const blocked = (msg) => [{
  json: {
    blocked: true,
    slack_url: 'https://slack.com/api/chat.postMessage',
    slack_payload: { channel: (job && job.channel) || r.channel, thread_ts: job ? job.thread_ts : undefined, text: msg },
  },
}];

if (!job || !job.plan) return blocked(':warning: I could not find this draft. Please ask for a new campaign.');
if (job.status !== 'awaiting_review') return blocked(`:information_source: This draft was already handled (status: ${job.status}).`);
if (!r.notes) return blocked(':information_source: No change notes were provided, so nothing was regenerated.');

const day = new Date().toISOString().slice(0, 10);
const used = (sd.usage && sd.usage[job.client_id] && sd.usage[job.client_id][day]) || 0;
if (used + 1 > job.limit) return blocked(`:no_entry: Daily image limit reached (${used} of ${job.limit}).`);

sd.learned = sd.learned || {};
sd.learned[job.client_id] = sd.learned[job.client_id] || [];
sd.learned[job.client_id].push({
  date: new Date().toISOString().slice(0, 10),
  rejected_element: `Draft revision request (${r.job_id})`,
  client_feedback: r.notes,
  corrective_rule: r.notes,
});
if (sd.learned[job.client_id].length > 20) sd.learned[job.client_id].shift();

job.revision = (job.revision || 0) + 1;
job.status = 'revising';
const p = job.plan.posts[0];

return [{
  json: {
    blocked: false,
    job_id: r.job_id,
    client_id: job.client_id,
    mode: 'draft',
    post_index: p.index,
    total: job.plan.posts.length,
    headline: p.headline_text,
    art_prompt: `${p.art_prompt} Client revision notes (must follow): ${r.notes}`,
    caption: p.caption,
    hashtags: p.hashtags,
    channel: job.channel,
    thread_ts: job.thread_ts,
    attempt: 1,
    max_retries: 2,
    qa_rules: job.qa_rules,
    qa_min_score: 80,
    revision_notes: r.notes,
    card_channel: job.card_channel,
    card_ts: job.card_ts,
  },
}];

// One Slack notice per approve or revision (even when several items are queued).
const s = $input.first().json;
if (s.mode === 'batch') {
  return [{
    json: {
      slack_url: 'https://slack.com/api/chat.update',
      slack_payload: {
        channel: s.card_channel,
        ts: s.card_ts,
        text: 'Approved, generating the rest of the campaign',
        blocks: [{
          type: 'section',
          text: { type: 'mrkdwn', text: `:white_check_mark: Approved by <@${s.approved_by}>. Generating posts 2 to ${s.total} now. Each image is checked before it is posted.` },
        }],
      },
    },
  }];
}
return [{
  json: {
    slack_url: 'https://slack.com/api/chat.postMessage',
    slack_payload: {
      channel: s.channel,
      thread_ts: s.thread_ts,
      text: `:arrows_counterclockwise: Regenerating the draft with your notes: _${s.revision_notes}_`,
    },
  },
}];

// Single entry point for rendering (first attempt and QA retries both come through here).
// The image size comes from the confirmed brief saved on the job.
const s = $input.first().json;
const sd = $getWorkflowStaticData('global');
const job = sd.jobs && sd.jobs[s.job_id];
return [{
  json: {
    ...s,
    base_art_prompt: s.base_art_prompt || s.art_prompt,
    aspect_ratio: (job && job.aspect_ratio) || 'ASPECT_4_5',
  },
}];

// Reads the Ideogram result, counts usage, and prepares the Vision QA prompt.
const state = $('Render Input').last().json;
const res = $input.first().json;
const url = res && res.data && res.data[0] && res.data[0].url;
if (!url) throw new Error('Ideogram returned no image: ' + JSON.stringify(res).slice(0, 300));

const sd = $getWorkflowStaticData('global');
sd.usage = sd.usage || {};
const day = new Date().toISOString().slice(0, 10);
sd.usage[state.client_id] = sd.usage[state.client_id] || {};
sd.usage[state.client_id][day] = (sd.usage[state.client_id][day] || 0) + 1;
for (const d of Object.keys(sd.usage[state.client_id])) {
  if (d < new Date(Date.now() - 30 * 86400 * 1000).toISOString().slice(0, 10)) delete sd.usage[state.client_id][d];
}

const qa_system_prompt = `You are a strict Vision QA inspector for advertising images.
Expected headline text: "${state.headline}". Read the text on the image and compare it character by character.
Client banned elements: ${state.qa_rules || 'none'}.
Check: (1) the headline is spelled exactly, (2) text is sharp and legible, (3) no distorted hands, faces, anatomy, fabric or embroidery, (4) none of the banned elements appear, (5) the look fits a premium brand.
Return ONLY JSON: {"detected_text": "<all text you can read on the image>", "legibility_score": <0-100>, "is_blurry": <bool>, "has_distortion": <bool>, "violates_banned_elements": <bool>, "pass": <bool>, "critique": "<specific, fixable problems>"}`;

return [{ json: { ...state, image_url: url, qa_system_prompt } }];

// Decides pass/fail from the REAL Vision QA result. Spelling is checked here in code, not trusted to the model.
const state = $('Collect Render Result').last().json;
let qa = {};
try {
  qa = JSON.parse($input.first().json.choices[0].message.content);
} catch (err) {
  qa = { parse_error: true, critique: 'QA response was not valid JSON' };
}

const norm = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9؀-ۿ]/g, '');
const want = norm(state.headline);
const got = norm(qa.detected_text);
const score = Number(qa.legibility_score) || 0;

const problems = [];
if (qa.parse_error) problems.push(qa.critique);
if (!want || !got.includes(want)) {
  problems.push(`Headline must read exactly "${state.headline}" but the image reads "${qa.detected_text || ''}"`);
}
if (score < state.qa_min_score) problems.push(`Legibility score ${score} is below ${state.qa_min_score}`);
if (qa.is_blurry) problems.push('Text or image is blurry');
if (qa.has_distortion) problems.push('Distorted hands, faces, fabric or embroidery');
if (qa.violates_banned_elements) problems.push('Contains a banned element');
if (qa.pass === false && qa.critique && problems.length === 0) problems.push(qa.critique);

const pass = problems.length === 0;
const canRetry = state.attempt <= state.max_retries;

return [{
  json: {
    ...state,
    qa: { pass, score, detected_text: qa.detected_text || '', problems, critique: qa.critique || '' },
    qa_pass: pass,
    proceed: pass || !canRetry,
  },
}];

// TEST MODE: stands in for Ideogram. Returns a free placeholder image (placehold.co) with the headline printed on it,
// in the same size as the brief, so download, Slack upload and the review card all run for real.
const s = $input.first().json;
const sizes = { ASPECT_4_5: '1080x1350', ASPECT_1_1: '1080x1080', ASPECT_9_16: '1080x1920', ASPECT_16_9: '1920x1080' };
const size = sizes[s.aspect_ratio] || sizes.ASPECT_4_5;
const url = `https://placehold.co/${size}/6B1E3A/F3E6D0/png?font=playfair-display&text=${encodeURIComponent(s.headline || 'TEST POST')}`;
return [{ json: { test_mode: true, data: [{ url, prompt: s.art_prompt }] } }];

// TEST MODE: stands in for GPT-4o Vision QA. Passes by default.
// Set TEST_MODE_QA_FAIL_FIRST=true in .env to fail the first attempt once, so you can watch the retry loop.
const s = $input.first().json;
const failOnce = $env.TEST_MODE_QA_FAIL_FIRST === 'true' && s.attempt === 1;
const qa = failOnce
  ? { detected_text: String(s.headline || '').replace(/E/, '3'), legibility_score: 70, is_blurry: false, has_distortion: false, violates_banned_elements: false, pass: false, critique: 'TEST MODE: simulated spelling error' }
  : { detected_text: s.headline, legibility_score: 95, is_blurry: false, has_distortion: false, violates_banned_elements: false, pass: true, critique: 'TEST MODE: QA simulated' };
return [{ json: { test_mode: true, choices: [{ message: { content: JSON.stringify(qa) } }] } }];

// Computes the file size and name needed by Slack's external upload API.
const state = $('Evaluate QA').last().json;
const input = $input.first();
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = (input.binary && input.binary.data && input.binary.data.mimeType) || 'image/png';
const ext = mime.includes('jpeg') ? 'jpg' : mime.includes('webp') ? 'webp' : 'png';
const filename = `${state.client_id}-${state.job_id}-post${state.post_index}.${ext}`;
return [{ json: { ...state, filename, file_length: buf.length } }];

// Re-attaches the downloaded image to the item together with Slack's upload URL.
const state = $('Prepare Slack Upload').last().json;
const r = $input.first().json;
if (!r.ok) throw new Error('Slack files.getUploadURLExternal failed: ' + (r.error || JSON.stringify(r)));
return [{
  json: { ...state, upload_url: r.upload_url, file_id: r.file_id },
  binary: $('Download Image').last().binary,
}];

// Builds the Slack message for a finished image: a review card (draft) or a caption message (batch).
const s = $('Attach Image & Upload URL').last().json;
const sd = $getWorkflowStaticData('global');
const job = sd.jobs && sd.jobs[s.job_id];

const qaLine = s.qa.pass
  ? `:large_green_circle: *Vision QA passed* | legibility ${s.qa.score}/100 | text read: "${s.qa.detected_text}"`
  : `:large_orange_circle: *Vision QA did not fully pass after ${s.attempt} attempt(s):* ${s.qa.problems.join('; ')}`;
if (!s.qa.pass && job) job.qa_warnings = (job.qa_warnings || 0) + 1;

const captionText = `${s.caption}\n\n${s.hashtags}`.trim();
let payload;

if (s.mode === 'draft') {
  if (job) {
    job.status = 'awaiting_review';
    job.draft = { headline: s.headline, post_index: s.post_index, attempt: s.attempt, qa_pass: s.qa.pass };
  }
  const title = `Draft: Post ${s.post_index} of ${s.total}` + (job && job.revision ? ` (revision ${job.revision})` : '');
  payload = {
    channel: s.channel,
    thread_ts: s.thread_ts,
    text: `${title} is ready for review`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150) } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: qaLine.slice(0, 2900) }] },
      { type: 'section', text: { type: 'mrkdwn', text: `*Headline:* ${s.headline}\n*Proposed caption:*\n${captionText}`.slice(0, 2900) } },
      {
        type: 'actions',
        elements: [
          { type: 'button', text: { type: 'plain_text', text: `Approve and generate ${Math.max(s.total - 1, 0)} more posts` }, style: 'primary', action_id: 'btn_approve_batch', value: s.job_id },
          { type: 'button', text: { type: 'plain_text', text: 'Request changes' }, action_id: 'btn_request_edit', value: s.job_id },
          { type: 'button', text: { type: 'plain_text', text: 'Discard' }, style: 'danger', action_id: 'btn_discard', value: s.job_id },
        ],
      },
    ],
  };
} else {
  payload = {
    channel: s.channel,
    thread_ts: s.thread_ts,
    text: `*Post ${s.post_index} of ${s.total}: ${s.headline}*\n${captionText}\n${qaLine}`.slice(0, 3900),
  };
}

return [{
  json: {
    mode: s.mode,
    job_id: s.job_id,
    channel: s.channel,
    thread_ts: s.thread_ts,
    slack_url: 'https://slack.com/api/chat.postMessage',
    slack_payload: payload,
  },
}];

// Final message after all batch posts were delivered.
const s = $('Build Delivery Message').last().json;
const sd = $getWorkflowStaticData('global');
const job = sd.jobs && sd.jobs[s.job_id];
let warn = '';
if (job) {
  job.status = 'complete';
  if (job.qa_warnings) warn = ` ${job.qa_warnings} image(s) did not fully pass Vision QA, please review them.`;
}
return [{
  json: {
    slack_url: 'https://slack.com/api/chat.postMessage',
    slack_payload: {
      channel: s.channel,
      thread_ts: s.thread_ts,
      text: `:white_check_mark: Campaign complete. All images are saved in this thread.${warn}`,
    },
  },
}];
